import java.io.*;
import java.util.*;

public class Main {
    static PrintWriter out;
    static double EPS = 1e-9;
    static int INF = (int) 1e9;
    static long LINF = (long) 1e18;
    static int MOD = (int) 1e9 + 7;
    static double PI = Math.acos(-1);

    // Iterative version using explicit stack
    static int go(long n) {
        if (n == 0) return 0;
        Deque<long[]> stack = new ArrayDeque<>();
        stack.push(new long[]{n, 0, 0}); // {n, state, result} state 0=enter, 1=first branch done, 2=second branch done
        int[] results = new int[2];
        while (!stack.isEmpty()) {
            long[] cur = stack.pop();
            long val = cur[0];
            int state = (int) cur[1];
            if (state == 0) {
                if (val == 0) {
                    stack.push(new long[]{val, 2, 0}); // dummy, will be popped
                    continue;
                }
                long k = 1;
                int cnt = 1;
                while (k * 10 + 1 < val) {
                    k = k * 10 + 1;
                    cnt++;
                }
                long firstArg = val % k;
                long firstAdd = val / k * cnt;
                long secondArg = (k * 10 + 1 - val) % k;
                long secondAdd = (cnt + 1) + (k * 10 + 1 - val) / k * cnt;
                // Push current state to collect results
                stack.push(new long[]{val, 1, firstAdd, secondAdd, cnt, k}); // store extra info
                stack.push(new long[]{firstArg, 0, 0});
            } else if (state == 1) {
                // first branch result is in results[0] (from previous pop)
                int firstRes = results[0];
                long firstAdd = cur[2];
                long secondAdd = cur[3];
                int cnt = (int) cur[4];
                long k = cur[5];
                long secondArg = (k * 10 + 1 - cur[0]) % k;
                // push to compute second branch
                stack.push(new long[]{cur[0], 2, firstRes, firstAdd, secondAdd, cnt, k});
                stack.push(new long[]{secondArg, 0, 0});
            } else if (state == 2) {
                int firstRes = (int) cur[2];
                int secondRes = results[0];
                long firstAdd = cur[3];
                long secondAdd = cur[4];
                int res = (int) Math.min(firstRes + firstAdd, secondRes + secondAdd);
                results[0] = res;
            }
        }
        return results[0];
    }

    static void solve() {
        long n = new Scanner(System.in).nextLong();
        out.println(go(n));
    }

    public static void main(String[] args) {
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }
}
